/* Area 18 land classification: 120 x 88 WGS84-sampled hexes (34–61.5 E, 11.3–31.5 N).
   AREA18_LAND_BITS is the playable Arabian mainland and Bahrain, Farasan, Socotra
   and Masirah; AREA18_OUTSIDE_BITS is foreign land and out-of-theatre islands.
   Excluded land must be solid and impassable, NOT navigable sea.
   Coast is derived from playable land adjoining water in scenarios-area18.js.
   Based on an independently audited GSHHG coastline reference; narrow Masirah
   is retained by hand at playable hex resolution. Offline, MSB-first masks. */
(function(root){
  'use strict';
  const bits='';
  const outside='';
  root.AREA18_LAND_BITS=bits;
  root.AREA18_OUTSIDE_BITS=outside;
  // Retain original CommonJS return type for the scenario's Node loader.
  if(typeof module!=='undefined')module.exports=bits;
})(typeof window!=='undefined'?window:globalThis);
